// @ts-nocheck
// EnT-DB "submit" edge function (Supabase / Deno).
// Receives a form submission, recomputes the score on the server, stores the entry
// as "pending" and notifies the curator. GENERATED by tools/build-function.mjs from
// tools/function-template.ts and docs/assets/score.js: edit those, not this file.
//
// Secrets (Supabase dashboard -> Edge Functions -> Secrets). All optional except SITE_URL and IP_SALT:
//   SITE_URL        public address of the site, e.g. https://nuniwo-source.github.io/EnT-DB
//   RESEND_API_KEY  Resend API key; with NOTIFY_EMAIL, sends an email per submission
//   NOTIFY_EMAIL    where to send it; comma-separated for several curators
//   NOTIFY_FROM     sender, default "EnT-DB <onboarding@resend.dev>"
//   NTFY_TOPIC      ntfy.sh topic name; sends a phone push per submission
//   IP_SALT         any random string; salts the hash used for rate limiting (required)
//   SERVICE_KEY     only if the built-in SUPABASE_SERVICE_ROLE_KEY is missing: a secret (sb_secret_...) key
// Deploy with "Verify JWT" switched OFF: visitors are anonymous and send only the publishable key.

/*__SCORE_JS__*/

const EntScore = globalThis.EntScore;
const SB_URL = Deno.env.get("SUPABASE_URL");
const SB_KEY = Deno.env.get("SERVICE_KEY") || Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";
const MAX_PER_HOUR = 5;        // per visitor (best effort: the address comes from a proxy header)
const MAX_TOTAL_PER_HOUR = 30; // all visitors together: bounds the queue and the notifications

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, apikey, content-type, x-client-info",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};
function json(body, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: { ...CORS, "Content-Type": "application/json" } });
}
function rest(path, init = {}) {
  return fetch(`${SB_URL}/rest/v1/${path}`, {
    ...init,
    // "sb_secret_..." keys go in apikey only; a legacy service-role JWT is also sent as Bearer.
    headers: {
      apikey: SB_KEY, "Content-Type": "application/json",
      ...(SB_KEY.startsWith("sb_") ? {} : { Authorization: `Bearer ${SB_KEY}` }),
      ...(init.headers || {}),
    },
  });
}
async function sha256(text) {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
}
function esc(s) {
  return String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
}

// OpenChemLib is loaded lazily; if it cannot be loaded, submissions are refused until it can.
let oclCache;
async function loadOCL() {
  if (oclCache !== undefined) return oclCache;
  try {
    const m = await import("npm:openchemlib@8.19.0");
    oclCache = m?.default?.Molecule ? m.default : m?.Molecule ? m : null;
  } catch (_e) {
    oclCache = null;
  }
  return oclCache;
}
// -> { ok: true|false|null, idcode: string|null }
async function checkStructure(smiles) {
  const OCL = await loadOCL();
  if (!OCL) return { ok: null, idcode: null };
  try {
    const mol = OCL.Molecule.fromSmiles(smiles);
    if (!(mol.getAllAtoms() > 0)) return { ok: false, idcode: null };
    return { ok: true, idcode: mol.getIDCode() };
  } catch (_e) {
    return { ok: false, idcode: null };
  }
}
// -> true | false | null (null when doi.org could not be asked)
async function doiResolves(doi) {
  if (!/^10\.\d{4,9}\/\S+$/.test(doi)) return null;
  try {
    const r = await fetch(`https://doi.org/api/handles/${encodeURIComponent(doi)}`, { signal: AbortSignal.timeout(5000) });
    if (r.status === 404) return false;
    if (!r.ok) return null;
    const body = await r.json();
    return body?.responseCode === 1;
  } catch (_e) {
    return null;
  }
}

async function notify(row) {
  const site = (Deno.env.get("SITE_URL") || "").replace(/\/+$/, "");
  const reviewUrl = site ? `${site}/admin.html` : "";
  const grade = EntScore.gradeOf(row.score).label;
  const subject = `EnT-DB: new submission, ${row.name} (${row.score}/100, ${grade})`;
  const lines = [
    ["Molecule", row.name], ["SMILES", row.smiles], ["E_T", `${row.et_kcal} kcal/mol (reported: ${row.et_reported})`],
    ["Value type", row.et_type], ["Method", row.method], ["Conditions", row.conditions],
    ["Source", row.citation], ["DOI", row.doi], ["Where", row.location], ["Submitted by", row.submitted_by],
  ].filter((l) => l[1]);
  const lost = (row.score_items || []).filter((i) => i.got < i.max).map((i) => `${i.label} (${i.got}/${i.max})`);
  const jobs = [];

  const key = Deno.env.get("RESEND_API_KEY"), to = (Deno.env.get("NOTIFY_EMAIL") || "").split(",").map((s) => s.trim()).filter(Boolean);
  if (key && to.length) {
    const html = `<h2 style="font-family:sans-serif">New submission: ${esc(row.name)}</h2>
<p style="font-family:sans-serif"><b>Score ${row.score}/100 (${grade})</b>${lost.length ? "<br>Points lost on: " + esc(lost.join("; ")) : ""}</p>
<table style="font-family:sans-serif;border-collapse:collapse">${lines.map((l) => `<tr><td style="padding:2px 12px 2px 0;color:#666">${esc(l[0])}</td><td>${esc(l[1])}</td></tr>`).join("")}</table>
${reviewUrl ? `<p style="font-family:sans-serif"><a href="${esc(reviewUrl)}">Open the review queue</a> to approve or reject it.</p>` : ""}`;
    jobs.push(fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
      body: JSON.stringify({ from: Deno.env.get("NOTIFY_FROM") || "EnT-DB <onboarding@resend.dev>", to, subject, html }),
      signal: AbortSignal.timeout(8000),
    }).then((r) => { if (!r.ok) console.error("resend failed", r.status); }));
  }

  const topic = Deno.env.get("NTFY_TOPIC");
  if (topic) {
    const headers = { Title: "EnT-DB: new submission", Tags: "test_tube" };
    if (reviewUrl) headers.Click = reviewUrl;
    jobs.push(fetch(`https://ntfy.sh/${encodeURIComponent(topic)}`, {
      method: "POST", headers,
      body: `${row.name}: ${row.et_kcal} kcal/mol, score ${row.score}/100 (${grade})`,
      signal: AbortSignal.timeout(8000),
    }).then((r) => { if (!r.ok) console.error("ntfy failed", r.status); }));
  }
  await Promise.allSettled(jobs);   // a failed notification never fails the submission
}

// -> true when a limit is reached, false when not, null when the count failed.
// "extra" is the number of the visitor's own rows already stored (1 after the insert).
async function overLimits(ipHash, extra) {
  const since = encodeURIComponent(new Date(Date.now() - 3600 * 1000).toISOString());
  const [mine, all] = await Promise.all([
    rest(`entries?select=id&ip_hash=eq.${ipHash}&created_at=gte.${since}&limit=${MAX_PER_HOUR + 1}`),
    rest(`entries?select=id&ip_hash=not.is.null&created_at=gte.${since}&limit=${MAX_TOTAL_PER_HOUR + 1}`),
  ]);
  if (!mine.ok || !all.ok) return null;
  const [m, a] = [(await mine.json()).length, (await all.json()).length];
  return m > MAX_PER_HOUR - 1 + extra || a > MAX_TOTAL_PER_HOUR - 1 + extra;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: CORS });
  if (req.method !== "POST") return json({ error: "Use POST." }, 405);
  if (!SB_URL || !SB_KEY) return json({ error: "The server is not configured." }, 500);

  let payload;
  try {
    const text = await req.text();
    if (text.length > 20000) return json({ error: "The submission is too large." }, 400);
    payload = JSON.parse(text);
  } catch (_e) {
    return json({ error: "The submission could not be read." }, 400);
  }
  if (!payload || typeof payload !== "object") return json({ error: "The submission could not be read." }, 400);

  // Honeypot: real visitors never see or fill this field. Pretend it worked.
  if (String(payload.website || "").trim()) return json({ id: null, score: 0, grade: "Poor" });

  // Shared site login: enforced by the database, so it cannot be skipped from the browser.
  const acc = await rest("rpc/check_access", {
    method: "POST",
    body: JSON.stringify({ p_user: String(payload.access_user || "").slice(0, 100), p_pass: String(payload.access_pass || "").slice(0, 200) }),
  });
  if (!acc.ok) return json({ error: "The server could not check your access." }, 500);
  if ((await acc.json()) !== true) return json({ error: "Sign in to submit an entry." }, 401);

  const salt = Deno.env.get("IP_SALT");
  if (!salt) return json({ error: "The server is not configured." }, 500);
  const ip = (req.headers.get("x-forwarded-for") || "").split(",")[0].trim() || "unknown";
  const ipHash = await sha256(ip + "|" + salt);
  const tooMany = json({ error: "Too many submissions. Try again later." }, 429);
  const limits = await overLimits(ipHash, 0);
  if (limits === null) return json({ error: "The server could not check the submission limits." }, 500);
  if (limits) return tooMany;

  const f = EntScore.normalize(payload);
  const [structure, resolves] = await Promise.all([checkStructure(f.smiles), doiResolves(f.doi)]);
  if (structure.ok === null) return json({ error: "The structure could not be checked right now. Try again in a few minutes." }, 503);

  let same = null;
  if (structure.ok && structure.idcode) {
    // Compared with approved entries only, so unreviewed submissions cannot mark a genuine one as a duplicate.
    const r = await rest(`entries?select=name,doi,et_kcal,origin&status=eq.approved&idcode=eq.${encodeURIComponent(structure.idcode)}&limit=50`);
    same = r.ok ? await r.json() : null;
  }
  const ctx = { structureOk: structure.ok, doiResolves: resolves, same };

  const missing = EntScore.requiredError(f, ctx);
  if (missing) return json({ error: missing }, 400);

  const sc = EntScore.scoreEntry(f, ctx);
  const row = { ...EntScore.toDoc(f, sc), status: "pending", idcode: structure.idcode, ip_hash: ipHash };

  const ins = await rest("entries", { method: "POST", headers: { Prefer: "return=representation" }, body: JSON.stringify(row) });
  if (!ins.ok) {
    console.error("insert failed", ins.status, await ins.text());
    return json({ error: "The entry could not be stored." }, 500);
  }
  const saved = (await ins.json())[0];

  // Parallel requests can all pass the first check; whichever lands over a limit removes itself.
  if ((await overLimits(ipHash, 1)) !== false) {
    await rest(`entries?id=eq.${encodeURIComponent(saved.id)}`, { method: "DELETE" });
    return tooMany;
  }

  await notify(saved);
  return json({ id: saved.id, score: sc.total, grade: sc.grade });
});
